const T_LOW = '下肢拉伸';
const T_CAT = '猫牛式/脊柱';
const TC = { up: '#f59e0b', low: '#f97316', cat: '#eab308' };

const s = (date, note, kind) => ({
  id: 'c_s_' + date.replace(/-/g, ''), habitId: 'h_strength', date,
  selectedItems: [{ text: P[kind], color: C[kind] }],
  createdAt: date + 'T19:30:00+08:00', note
});
const c = (date, note, which) => {
  const items = (Array.isArray(which) ? which : [which]).map(k =>
    k === 'cardio' ? { text: CARDIO, color: CC } : { text: CORE, color: TE });
  return {
    id: 'c_c_' + date.replace(/-/g, ''), habitId: 'h_cardio', date,
    selectedItems: items, createdAt: date + 'T20:15:00+08:00', note
  };
};
const TMAP = { up: { text: T_UP, color: TC.up }, low: { text: T_LOW, color: TC.low }, cat: { text: T_CAT, color: TC.cat } };

const t = (date, note, keys) => ({
  id: 'c_t_' + date.replace(/-/g, ''), habitId: 'h_stretch', date,
  selectedItems: keys.map(k => TMAP[k]),
  createdAt: date + 'T20:35:00+08:00', note
});
const w = (date, note) => ({
  id: 'c_w_' + date.replace(/-/g, ''), habitId: 'h_weight', date,
  selectedItems: [], createdAt: date + 'T07:30:00+08:00', note
});

