const seen = new Set(d.checkins.map(x => x.habitId + '|' + x.date));
let n = 0, skipped = [];
for (const x of added) {
  const k = x.habitId + '|' + x.date;
  if (seen.has(k)) { skipped.push(k); continue; }
  seen.add(k);
  d.checkins.push(x);
  n++;
}
d.checkins.sort((a, b) => (a.date < b.date ? -1 : a.date > b.date ? 1 : (a.habitId < b.habitId ? -1 : 1)));

d.settings.slogan = '先把周期养回来，臀围88→90';
d.settings.fitnessProfile = require('./fitness-profile-20260909.js');

const out = JSON.stringify(d, null, 2);
fs.writeFileSync(FILE, out, 'utf8');

// 自查：habitId 全部可解析、同 habit+date 无重复、createdAt 全带 +08:00
const ids = new Set(d.habits.map(h => h.id));
const bad1 = d.checkins.filter(x => !ids.has(x.habitId));
const dup = {};
for (const x of d.checkins) { const k = x.habitId + '|' + x.date; dup[k] = (dup[k] || 0) + 1; }
const bad2 = Object.entries(dup).filter(([, v]) => v > 1);
const bad3 = d.checkins.filter(x => !/\+08:00$/.test(x.createdAt));
const bad4 = d.checkins.filter(x => !x.id || !x.note);
console.log('added', n, 'skipped(dup)', skipped.join(',') || 'none', '| total checkins', d.checkins.length);
console.log('selfcheck badHabitId', bad1.length, '| dupDate', bad2.length, '| noTZ', bad3.length, '| missingField', bad4.length);
console.log('profile chars', d.settings.fitnessProfile.length);
console.log('file bytes', Buffer.byteLength(out, 'utf8'));
console.log('date range', d.checkins[0].date, '->', d.checkins[d.checkins.length - 1].date);
